const lockTaskMergeJobForResult = `-- name: LockTaskMergeJobForResult :one
SELECT
    task_merge_jobs.id, task_merge_jobs.company_id, task_merge_jobs.task_id, task_merge_jobs.run_id, task_merge_jobs.task_execution_generation, task_merge_jobs.authority_user_id, task_merge_jobs.request_type, task_merge_jobs.status, task_merge_jobs.attempt_count, task_merge_jobs.next_attempt_at, task_merge_jobs.lease_expires_at, task_merge_jobs.result_code, task_merge_jobs.merged_commit, task_merge_jobs.created_at, task_merge_jobs.updated_at, task_merge_jobs.completed_at,
    tasks.conversation_id,
    CAST(
        COALESCE(task_merge_jobs.lease_expires_at > clock_timestamp(), false)
        AS boolean
    ) AS lease_active
FROM task_merge_jobs
JOIN runs
  ON runs.id = task_merge_jobs.run_id
 AND runs.company_id = task_merge_jobs.company_id
 AND runs.task_id = task_merge_jobs.task_id
 AND runs.task_execution_generation = task_merge_jobs.task_execution_generation
JOIN runtimes
  ON runtimes.id = runs.runtime_id
 AND runtimes.company_id = runs.company_id
JOIN company_members AS daemon_member
  ON daemon_member.company_id = runs.company_id
 AND daemon_member.user_id = $1::uuid
 AND daemon_member.status = 'active'
JOIN tasks
  ON tasks.id = task_merge_jobs.task_id
 AND tasks.company_id = task_merge_jobs.company_id
WHERE task_merge_jobs.id = $2::uuid
  AND runtimes.id = $3::uuid
  AND runtimes.daemon_id = $4::text
  AND task_merge_jobs.attempt_count = $5::integer
FOR UPDATE OF task_merge_jobs
`

