const supersedePendingTaskMergeJobsForTask = `-- name: SupersedePendingTaskMergeJobsForTask :execrows
UPDATE task_merge_jobs
SET status = 'blocked',
    result_code = 'superseded',
    merged_commit = NULL,
    lease_expires_at = NULL,
    completed_at = clock_timestamp(),
    updated_at = clock_timestamp()
WHERE task_id = $1::uuid
  AND status = 'pending'
`

func (q *Queries) SupersedePendingTaskMergeJobsForTask(ctx context.Context, taskID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, supersedePendingTaskMergeJobsForTask, taskID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
